use serde_json::Value;
use crate::animation::Vec3;
#[derive(Clone,Copy,Default)]pub struct BehaviorContext{pub frame:f64,pub start:f64,pub duration:f64,pub index:usize,pub count:usize,pub seed:f64,pub energy:f64,pub low:f64,pub mid:f64,pub high:f64}
fn n(v:Option<&Value>,d:f64)->f64{v.and_then(Value::as_f64).unwrap_or(d)}fn p(c:BehaviorContext)->f64{((c.frame-c.start)/c.duration.max(1.0)).max(0.0).min(1.0)}fn noise(seed:f64,x:f64)->f64{let v=((seed+1.0)*91.17+x*12.9898).sin()*43758.5453;(v-v.floor())*2.0-1.0}
fn v3(v:Option<&Value>,d:Vec3)->Vec3{v.and_then(Value::as_array).map(|a|[a.first().and_then(Value::as_f64).unwrap_or(d[0]),a.get(1).and_then(Value::as_f64).unwrap_or(d[1]),a.get(2).and_then(Value::as_f64).unwrap_or(d[2])]).unwrap_or(d)}
pub fn apply_number(mut base:f64,behaviors:Option<&Vec<Value>>,c:BehaviorContext)->f64{for b in behaviors.into_iter().flatten(){if b.get("enabled").and_then(Value::as_bool)==Some(false){continue}let kind=b.get("type").and_then(Value::as_str).unwrap_or("");let params=b.get("params").unwrap_or(&Value::Null);let q=p(c);base=match kind{"fade"=>{let from=n(params.get("from"),0.0);from+(n(params.get("to"),base)-from)*q},"drift"=>base+n(params.get("amount"),1.0)*q,"wiggle"=>base+noise(n(b.get("seed"),c.seed),c.frame*n(params.get("frequency"),0.1))*n(params.get("amplitude"),n(params.get("amount"),1.0)),"audio-react"=>{let sig=params.get("signal").and_then(Value::as_str).unwrap_or("energy");let a=match sig{"low"=>c.low,"mid"=>c.mid,"high"=>c.high,_=>c.energy};base+a*n(params.get("amount"),1.0)},_=>base};}base}
pub fn apply_vec3(mut base:Vec3,behaviors:Option<&Vec<Value>>,c:BehaviorContext)->Vec3{for b in behaviors.into_iter().flatten(){if b.get("enabled").and_then(Value::as_bool)==Some(false){continue}let kind=b.get("type").and_then(Value::as_str).unwrap_or("");let params=b.get("params").unwrap_or(&Value::Null);let q=p(c);base=match kind{"slide"=>{let from=v3(params.get("from"),[0.0,0.0,0.0]);[base[0]+from[0]*(1.0-q),base[1]+from[1]*(1.0-q),base[2]+from[2]*(1.0-q)]},"drift"=>{let d=v3(params.get("offset"),[0.0,0.0,0.0]);[base[0]+d[0]*q,base[1]+d[1]*q,base[2]+d[2]*q]},"wiggle"=>{let amp=v3(params.get("amplitude"),[10.0,10.0,10.0]);let f=n(params.get("frequency"),0.1);let seed=n(b.get("seed"),c.seed);[base[0]+noise(seed,c.frame*f)*amp[0],base[1]+noise(seed+1.0,c.frame*f)*amp[1],base[2]+noise(seed+2.0,c.frame*f)*amp[2]]},"audio-react"=>{let sig=params.get("signal").and_then(Value::as_str).unwrap_or("energy");let a=match sig{"low"=>c.low,"mid"=>c.mid,"high"=>c.high,_=>c.energy};let amount=v3(params.get("amount"),[1.0,1.0,1.0]);[base[0]+a*amount[0],base[1]+a*amount[1],base[2]+a*amount[2]]},_=>base};}base}
